INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('push toward profitability', '推進盈利；朝盈利方向努力', 'to take actions that move a business closer to generating profit', '[{"en":"The board urged management to push toward profitability.","zh-TW":"董事會敦促管理層推進盈利。"},{"en":"Every initiative should push us toward profitability.","zh-TW":"每個計劃都應該讓我們朝盈利方向努力。"}]', 'phrasal verb'),
('put into practice', '付諸實踐；實際運用', 'to actually use or apply knowledge, a plan, or an idea', '[{"en":"The challenge is putting strategy into practice.","zh-TW":"挑戰在於將策略付諸實踐。"},{"en":"Put the training insights into practice from day one.","zh-TW":"從第一天開始將培訓洞察實際運用。"}]', 'expression'),
('rally the troops', '鼓舞士氣；激勵團隊', 'to inspire and motivate a group of people to take action', '[{"en":"The manager rallied the troops before the product launch.","zh-TW":"經理在產品發布前鼓舞了團隊士氣。"},{"en":"Rally the troops with a clear vision and concrete action plan.","zh-TW":"用清晰的願景和具體的行動計劃激勵團隊。"}]', 'expression'),
('reach a consensus', '達成共識；取得一致意見', 'to achieve general agreement among all members of a group', '[{"en":"The committee reached a consensus after three hours of debate.","zh-TW":"委員會在三小時的辯論後達成了共識。"},{"en":"Reach a consensus on priorities before starting the project.","zh-TW":"在開始專案前對優先事項取得一致意見。"}]', 'expression'),
('retain talent', '留住人才；保留優秀員工', 'to keep valuable employees from leaving the organization', '[{"en":"We invest in culture to retain talent long-term.","zh-TW":"我們投資於文化以長期留住人才。"},{"en":"Retaining talent is cheaper than replacing it.","zh-TW":"留住人才比替換人才的成本更低。"}]', 'phrasal verb'),
('revenue recognition', '收入認列；收入確認', 'the accounting principle of when and how revenue is recorded', '[{"en":"Revenue recognition rules affected our quarterly reporting.","zh-TW":"收入認列規則影響了我們的季度報告。"},{"en":"Understand revenue recognition before structuring multi-year deals.","zh-TW":"在制定多年交易結構之前了解收入確認規則。"}]', 'business idiom'),
('reverse engineer', '逆向工程；反推分析', 'to analyze how something works by working backward from the result', '[{"en":"We reverse engineered the competitor''s pricing model.","zh-TW":"我們對競爭對手的定價模型進行了反推分析。"},{"en":"Reverse engineer your desired outcome to build your plan.","zh-TW":"從你期望的結果反推來建立你的計劃。"}]', 'phrasal verb'),
('right person right role', '人崗匹配；適才適所', 'placing individuals in positions that match their skills and strengths', '[{"en":"The right person in the right role maximizes team output.","zh-TW":"人崗匹配使團隊產出最大化。"},{"en":"Evaluate roles annually to ensure right person right role.","zh-TW":"每年評估職位以確保適才適所。"}]', 'expression'),
('risk tolerance', '風險承受度；風險承受能力', 'the degree of variability in outcomes an entity is willing to accept', '[{"en":"Define your risk tolerance before entering volatile markets.","zh-TW":"在進入波動市場前確定你的風險承受度。"},{"en":"Risk tolerance varies across business units.","zh-TW":"各業務部門的風險承受能力各不相同。"}]', 'business idiom'),
('road test', '試行；實際測試', 'to test something in real-world conditions before full deployment', '[{"en":"We road tested the new interface with 50 users.","zh-TW":"我們與50位用戶試行了新界面。"},{"en":"Road test your message with a small audience first.","zh-TW":"先與小部分受眾實際測試你的信息。"}]', 'phrasal verb'),
('roll out across', '在…全面推出；跨範圍部署', 'to deploy or implement something across all locations or units', '[{"en":"The new ERP will roll out across all regions in Q2.","zh-TW":"新ERP將在第二季在所有地區全面推出。"},{"en":"Roll out the training across all levels simultaneously.","zh-TW":"在所有層級同時跨範圍部署培訓。"}]', 'phrasal verb'),
('safe to fail', '容許失敗；可以安全失敗', 'an environment where trying new things and failing is acceptable and encouraged', '[{"en":"We create a safe to fail environment for innovation.","zh-TW":"我們為創新建立容許失敗的環境。"},{"en":"A safe to fail culture enables faster learning.","zh-TW":"容許失敗的文化使學習更快。"}]', 'expression'),
('saturate the market', '佔領市場；充斥市場', 'to supply a market so fully that there is no room for growth', '[{"en":"We saturated the market with advertising before the launch.","zh-TW":"發布前我們用廣告佔領了市場。"},{"en":"Once you saturate the market focus on adjacent opportunities.","zh-TW":"一旦充斥市場就專注於相鄰的機會。"}]', 'phrasal verb'),
('sell the dream', '販賣夢想；推銷願景', 'to market a product or service based on an aspirational vision', '[{"en":"Early-stage startups must sell the dream to attract investors.","zh-TW":"早期新創公司必須向投資者販賣夢想。"},{"en":"Sell the dream but deliver on the fundamentals.","zh-TW":"販賣夢想但要落實基本功。"}]', 'expression'),
('serial entrepreneur', '連續創業者', 'a person who repeatedly starts new businesses after selling or completing previous ones', '[{"en":"As a serial entrepreneur she has launched five companies.","zh-TW":"作為連續創業者她已經創辦了五家公司。"},{"en":"Serial entrepreneurs apply lessons from each venture to the next.","zh-TW":"連續創業者將每次創業的教訓應用到下一次。"}]', 'business idiom'),
('shareholder value', '股東價值', 'the value delivered to equity owners of a corporation', '[{"en":"Every major decision must be evaluated for its impact on shareholder value.","zh-TW":"每個重大決策都必須評估其對股東價值的影響。"},{"en":"Long-term shareholder value comes from sustainable operations.","zh-TW":"長期股東價值來自可持續的運營。"}]', 'business idiom'),
('short-term pain for long-term gain', '短期陣痛換取長期收益', 'accepting current difficulties to achieve better results in the future', '[{"en":"Cost cuts now are short-term pain for long-term gain.","zh-TW":"現在的成本削減是短期陣痛換取長期收益。"},{"en":"Investing in new technology is short-term pain for long-term gain.","zh-TW":"投資新技術是短期陣痛換取長期收益。"}]', 'expression'),
('situational awareness', '情境意識；掌握局勢', 'the ability to understand and respond to one''s current environment effectively', '[{"en":"Situational awareness helps leaders make timely decisions.","zh-TW":"情境意識幫助領導者做出及時的決策。"},{"en":"Develop situational awareness by listening to frontline feedback.","zh-TW":"通過傾聽一線反饋培養情境意識。"}]', 'business idiom'),
('slash costs', '大幅削減成本', 'to reduce costs dramatically and quickly', '[{"en":"The company slashed costs by 30% through automation.","zh-TW":"公司通過自動化大幅削減了30%的成本。"},{"en":"Slashing costs too aggressively can harm quality.","zh-TW":"過於激進地大幅削減成本可能損害品質。"}]', 'phrasal verb'),
('social proof', '社交證明；口碑效應', 'evidence that others are using and endorsing a product or service', '[{"en":"Customer testimonials serve as social proof.","zh-TW":"客戶見證充當社交證明。"},{"en":"Social proof reduces purchase hesitation among new customers.","zh-TW":"社交證明減少了新客戶的購買猶豫。"}]', 'business idiom'),
('soft skills', '軟技能；人際技能', 'interpersonal and communication abilities as opposed to technical skills', '[{"en":"Soft skills like empathy are crucial for effective leadership.","zh-TW":"同理心等軟技能對有效領導至關重要。"},{"en":"We train both hard and soft skills across all levels.","zh-TW":"我們在各層級同時培訓硬技能和軟技能。"}]', 'business idiom'),
('sole proprietor', '獨資經營者；個人業主', 'an individual who owns and operates a business alone with full liability', '[{"en":"She started as a sole proprietor before registering a company.","zh-TW":"她在登記公司之前以獨資方式開始業務。"},{"en":"A sole proprietor takes on all business risks personally.","zh-TW":"獨資經營者個人承擔所有業務風險。"}]', 'business idiom'),
('speculate on', '推測；猜測；投機於', 'to form opinions without full evidence; to invest in high-risk assets', '[{"en":"Don''t speculate on results before the data is in.","zh-TW":"在數據出來之前不要推測結果。"},{"en":"Avoid speculating on commodities without expertise.","zh-TW":"沒有專業知識不要投機於商品市場。"}]', 'phrasal verb'),
('stakeholder map', '利益相關者地圖', 'a diagram showing all stakeholders and their relationships to a project', '[{"en":"A stakeholder map helps prioritize communication efforts.","zh-TW":"利益相關者地圖幫助優先安排溝通工作。"},{"en":"Build a stakeholder map before starting any major initiative.","zh-TW":"在開始任何重大計劃之前建立利益相關者地圖。"}]', 'business idiom'),
('strategic partnership', '戰略合作關係；策略聯盟', 'a formal alliance between organizations for mutual strategic benefit', '[{"en":"We formed a strategic partnership to enter the Asian market.","zh-TW":"我們建立了戰略合作關係以進入亞洲市場。"},{"en":"A strategic partnership accelerates growth beyond organic means.","zh-TW":"戰略合作關係使增長超越了有機手段。"}]', 'business idiom'),
('subject matter expert', '主題專家；領域專家', 'a person with deep knowledge or expertise in a particular area', '[{"en":"We brought in a subject matter expert on GDPR compliance.","zh-TW":"我們引進了GDPR合規方面的主題專家。"},{"en":"Subject matter experts reduce costly errors in specialized work.","zh-TW":"領域專家減少了專業工作中代價高昂的錯誤。"}]', 'business idiom'),
('succession planning', '繼任計劃；接班規劃', 'preparing and identifying future leaders to fill key positions', '[{"en":"Succession planning ensures business continuity.","zh-TW":"繼任計劃確保了業務連續性。"},{"en":"Start succession planning early to avoid talent gaps.","zh-TW":"提早開始接班規劃以避免人才缺口。"}]', 'business idiom'),
('supply chain resilience', '供應鏈韌性；供應鏈抗風險能力', 'the ability of a supply chain to recover quickly from disruptions', '[{"en":"Diversifying suppliers improves supply chain resilience.","zh-TW":"多樣化供應商提高了供應鏈韌性。"},{"en":"Supply chain resilience became a boardroom priority after the pandemic.","zh-TW":"疫情後供應鏈抗風險能力成為了董事會的優先事項。"}]', 'business idiom'),
('surge in demand', '需求激增；需求驟升', 'a sudden and sharp increase in demand for a product or service', '[{"en":"A surge in demand during the holidays strained our inventory.","zh-TW":"假日期間需求激增使我們的庫存緊張。"},{"en":"We scaled up production to meet the surge in demand.","zh-TW":"我們擴大了生產以滿足需求驟升。"}]', 'expression'),
('swing for the fences', '放手一搏；雄心勃勃', 'to aim for the highest possible outcome, accepting greater risk', '[{"en":"We swung for the fences with a bold new market entry.","zh-TW":"我們以大膽的新市場進入放手一搏。"},{"en":"Sometimes you need to swing for the fences to win big.","zh-TW":"有時你需要放手一搏才能大獲全勝。"}]', 'expression'),
('synergy between', '兩者之間的協同效應', 'mutual benefit or enhanced effectiveness that comes from two things working together', '[{"en":"There is strong synergy between our sales and marketing teams.","zh-TW":"我們的銷售和行銷團隊之間有強大的協同效應。"},{"en":"The merger created synergy between complementary product lines.","zh-TW":"合併在互補的產品線之間創造了協同效應。"}]', 'prepositional phrase'),
('talent acquisition', '人才招募；人才獲取', 'the process of finding and hiring skilled employees', '[{"en":"Talent acquisition is a key investment for our expansion.","zh-TW":"人才招募是我們擴張的關鍵投資。"},{"en":"A strong employer brand supports talent acquisition.","zh-TW":"強大的雇主品牌支持人才招募。"}]', 'business idiom'),
('talent pipeline', '人才儲備；人才管道', 'a pool of qualified candidates prepared to fill future vacancies', '[{"en":"Building a talent pipeline prevents urgent hiring mistakes.","zh-TW":"建立人才儲備防止緊急招聘的錯誤。"},{"en":"Internship programs feed directly into our talent pipeline.","zh-TW":"實習計劃直接補充我們的人才管道。"}]', 'business idiom'),
('total addressable market', '總可服務市場；市場總規模', 'the total revenue opportunity available if a company achieves 100% market share', '[{"en":"The total addressable market for our product is 50 billion dollars.","zh-TW":"我們產品的總可服務市場為500億美元。"},{"en":"Define the total addressable market before seeking funding.","zh-TW":"在尋求融資之前定義總可服務市場。"}]', 'business idiom'),
('track record', '過往記錄；業績記錄', 'a record of past achievements or failures used to judge future performance', '[{"en":"Our track record of successful launches builds client confidence.","zh-TW":"我們成功發布的過往記錄建立了客戶信心。"},{"en":"Investors look at the team''s track record before funding.","zh-TW":"投資者在融資前查看團隊的業績記錄。"}]', 'business idiom'),
('transition period', '過渡期；交接期', 'the time during which change is occurring from one state to another', '[{"en":"Communicate clearly during the transition period.","zh-TW":"在過渡期間清晰溝通。"},{"en":"The transition period requires extra support for affected teams.","zh-TW":"交接期需要對受影響的團隊提供額外支持。"}]', 'business idiom'),
('transparent communication', '透明溝通', 'open and honest sharing of information with relevant parties', '[{"en":"Transparent communication builds trust with stakeholders.","zh-TW":"透明溝通建立了與利益相關者的信任。"},{"en":"We practice transparent communication at all levels.","zh-TW":"我們在各層級實踐透明溝通。"}]', 'business idiom'),
('turnover rate', '人員流動率；離職率', 'the rate at which employees leave and are replaced in an organization', '[{"en":"A high turnover rate is costly and disrupts culture.","zh-TW":"高離職率代價高昂且破壞文化。"},{"en":"We reduced turnover rate by 40% with flexible work policies.","zh-TW":"我們通過彈性工作政策將離職率降低了40%。"}]', 'business idiom'),
('two-track approach', '雙軌策略；兩路並進', 'pursuing two different strategies or channels simultaneously', '[{"en":"We used a two-track approach — organic growth and acquisitions.","zh-TW":"我們採用了雙軌策略——有機增長和收購並進。"},{"en":"A two-track approach reduces risk by diversifying efforts.","zh-TW":"兩路並進通過多元化努力降低了風險。"}]', 'business idiom'),
('underperforming asset', '表現不佳的資產；低效資產', 'an asset that is not generating returns in line with expectations', '[{"en":"We divested underperforming assets to free up capital.","zh-TW":"我們剝離了低效資產以釋放資金。"},{"en":"Identify underperforming assets and decide to fix or exit.","zh-TW":"識別表現不佳的資產並決定修復還是退出。"}]', 'business idiom'),
('up and running', '正常運作；啟動運行', 'functioning and operating as expected', '[{"en":"We had the new CRM up and running within a week.","zh-TW":"我們在一週內讓新CRM系統正常運作了。"},{"en":"Get the team up and running before the launch window closes.","zh-TW":"在發布窗口關閉之前讓團隊啟動運行。"}]', 'expression'),
('upmarket', '高端市場；高檔的', 'targeting wealthier or more sophisticated customers or products', '[{"en":"We repositioned the brand upmarket to improve margins.","zh-TW":"我們將品牌重新定位到高端市場以提高利潤率。"},{"en":"Moving upmarket requires investment in quality and service.","zh-TW":"進入高端市場需要在品質和服務上的投資。"}]', 'business idiom'),
('upside potential', '上升空間；增長潛力', 'the potential for value, revenue, or performance to increase further', '[{"en":"The upside potential of this market is enormous.","zh-TW":"這個市場的上升空間是巨大的。"},{"en":"We invested because the upside potential outweighed the risk.","zh-TW":"我們投資是因為增長潛力超過了風險。"}]', 'business idiom'),
('validate assumptions', '驗證假設', 'to test whether your beliefs or predictions about a situation are correct', '[{"en":"Validate assumptions with real user data before scaling.","zh-TW":"在擴大規模之前用真實用戶數據驗證假設。"},{"en":"We validated our assumptions with a small focus group.","zh-TW":"我們用小型焦點小組驗證了我們的假設。"}]', 'phrasal verb'),
('value chain', '價值鏈', 'the series of activities through which a company creates value for its customers', '[{"en":"We optimize every step in the value chain to reduce costs.","zh-TW":"我們優化價值鏈中的每一個步驟以降低成本。"},{"en":"Understanding the value chain reveals opportunities for improvement.","zh-TW":"了解價值鏈揭示了改進的機會。"}]', 'business idiom'),
('verify accuracy', '核實準確性；確認精確度', 'to confirm that information or data is correct and precise', '[{"en":"Always verify the accuracy of financial data before reporting.","zh-TW":"報告前務必核實財務數據的準確性。"},{"en":"Verify accuracy by cross-checking multiple sources.","zh-TW":"通過交叉核查多個來源確認精確度。"}]', 'phrasal verb'),
('vertical market', '垂直市場；特定行業市場', 'a market focusing on a specific industry or group of customers with similar needs', '[{"en":"We focus on the healthcare vertical market for deeper expertise.","zh-TW":"我們專注於醫療保健垂直市場以積累更深的專業知識。"},{"en":"Vertical market specialization improves sales conversion rates.","zh-TW":"垂直市場專業化提高了銷售轉換率。"}]', 'business idiom'),
('visibility into', '對…的可見度；對…的了解', 'the ability to see or understand what is happening in a process or area', '[{"en":"We need better visibility into our supply chain costs.","zh-TW":"我們需要對供應鏈成本有更好的可見度。"},{"en":"Real-time dashboards provide visibility into key metrics.","zh-TW":"即時儀表板提供了對關鍵指標的了解。"}]', 'expression'),
('walk the talk', '言行一致；知行合一', 'to actually do the things you say or promise, not just talk about them', '[{"en":"Leaders must walk the talk on work-life balance.","zh-TW":"領導者必須在工作與生活平衡上言行一致。"},{"en":"Walk the talk to earn respect from your team.","zh-TW":"知行合一以從團隊中贏得尊重。"}]', 'expression'),
('watch your back', '小心謹慎；提防他人', 'to be careful and protect yourself from potential threats', '[{"en":"In highly competitive markets you need to watch your back.","zh-TW":"在競爭激烈的市場中你需要小心謹慎。"},{"en":"Watch your back when entering a new territory alone.","zh-TW":"單獨進入新市場時要提防他人。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('waterfall methodology', '瀑布式開發方法', 'a sequential project management approach where each phase must complete before the next begins', '[{"en":"We use waterfall methodology for compliance-heavy projects.","zh-TW":"我們對合規要求高的專案使用瀑布式開發方法。"},{"en":"Waterfall methodology works well when requirements are stable.","zh-TW":"當需求穩定時瀑布式開發方法效果良好。"}]', 'business idiom'),
('weigh the pros and cons', '權衡利弊；評估優缺點', 'to carefully consider the advantages and disadvantages of a decision', '[{"en":"Weigh the pros and cons before committing to the vendor.","zh-TW":"在確定供應商之前權衡利弊。"},{"en":"We weighed the pros and cons of each market entry strategy.","zh-TW":"我們評估了每種市場進入策略的優缺點。"}]', 'expression'),
('what''s in it for me', '我能得到什麼；對我有什麼好處', 'the question of personal or organizational benefit from an action', '[{"en":"Always answer the what''s in it for me question for your client.","zh-TW":"始終為你的客戶回答我能得到什麼的問題。"},{"en":"People adopt change when they understand what''s in it for them.","zh-TW":"當人們了解對他們有什麼好處時他們才會接受改變。"}]', 'expression'),
('white glove service', '白手套服務；最高端的個性化服務', 'an exceptionally high level of personalized, attentive service', '[{"en":"We offer white glove service to our top 10 clients.","zh-TW":"我們向前10名客戶提供白手套服務。"},{"en":"White glove service commands a significant price premium.","zh-TW":"最高端的個性化服務可以定顯著的溢價。"}]', 'expression'),
('win at all costs', '不惜一切代價贏得；不擇手段', 'to be determined to succeed regardless of the means or consequences', '[{"en":"A win at all costs approach often damages long-term relationships.","zh-TW":"不惜一切代價的做法往往損害了長期關係。"},{"en":"Avoid win at all costs thinking in partnerships.","zh-TW":"在合作關係中避免不擇手段的想法。"}]', 'expression'),
('win the argument', '贏得爭論；說服對方', 'to successfully persuade others that your position is correct', '[{"en":"Win the argument with data not just opinions.","zh-TW":"用數據而不只是意見贏得爭論。"},{"en":"She won the argument by presenting a clear cost-benefit analysis.","zh-TW":"她通過提出清晰的成本效益分析說服了對方。"}]', 'expression'),
('word of mouth', '口口相傳；口碑', 'the passing of information or recommendations by spoken communication', '[{"en":"Most of our early growth came from word of mouth.","zh-TW":"我們早期的大部分增長來自口口相傳。"},{"en":"Word of mouth remains the most trusted form of marketing.","zh-TW":"口碑仍然是最受信任的行銷形式。"}]', 'business idiom'),
('work backward from', '從…倒推；從目標倒推計劃', 'to plan by starting from the desired end result and working toward the present', '[{"en":"Work backward from the launch date to set milestones.","zh-TW":"從發布日期倒推以設定里程碑。"},{"en":"She worked backward from the target revenue to build the plan.","zh-TW":"她從目標收入倒推建立了計劃。"}]', 'phrasal verb'),
('working capital', '運營資金；流動資金', 'the funds available for day-to-day business operations', '[{"en":"Proper working capital management ensures smooth operations.","zh-TW":"適當的運營資金管理確保了業務順暢。"},{"en":"A working capital shortage can stall growth.","zh-TW":"流動資金短缺可能會停滯增長。"}]', 'business idiom'),
('write the book on', '在某方面是頂級專家', 'to be the definitive expert on a particular subject', '[{"en":"She practically wrote the book on enterprise sales strategy.","zh-TW":"她在企業銷售策略上幾乎是頂級專家。"},{"en":"They write the book on efficient supply chain management.","zh-TW":"他們在高效供應鏈管理方面是頂級專家。"}]', 'expression'),
('zero-based budgeting', '零基預算', 'a budgeting method where all expenses must be justified from scratch each period', '[{"en":"We adopted zero-based budgeting to eliminate unnecessary spend.","zh-TW":"我們採用了零基預算以消除不必要的支出。"},{"en":"Zero-based budgeting forces discipline in resource allocation.","zh-TW":"零基預算強制了資源分配的紀律。"}]', 'business idiom'),
('act as a catalyst', '起催化劑作用；促進發展', 'to trigger or accelerate a process or change', '[{"en":"The new CEO acted as a catalyst for cultural transformation.","zh-TW":"新任執行長作為文化轉型的催化劑。"},{"en":"Technology acts as a catalyst for business model innovation.","zh-TW":"技術作為商業模式創新的催化劑。"}]', 'expression'),
('adapt or die', '適應或被淘汰', 'the necessity to evolve with changing conditions or face failure', '[{"en":"In today''s digital market it''s adapt or die.","zh-TW":"在今天的數位市場中就是適應或被淘汰。"},{"en":"Brands that fail to adapt or die end up irrelevant.","zh-TW":"不能適應的品牌最終會被淘汰。"}]', 'expression'),
('advocate loudly', '大聲倡導；積極推動', 'to actively and strongly promote a cause or idea', '[{"en":"She advocates loudly for diversity and inclusion.","zh-TW":"她積極推動多樣性和包容性。"},{"en":"Advocate loudly for resources your team needs.","zh-TW":"大聲倡導你的團隊所需的資源。"}]', 'phrasal verb'),
('at a watershed moment', '在關鍵轉折點；在歷史性時刻', 'at a turning point that marks a significant change', '[{"en":"The industry is at a watershed moment with AI adoption.","zh-TW":"行業在人工智慧採用方面處於關鍵轉折點。"},{"en":"We are at a watershed moment — act decisively.","zh-TW":"我們處於歷史性時刻——果斷行動。"}]', 'prepositional phrase'),
('attract investment', '吸引投資', 'to draw in financial backing from investors', '[{"en":"Strong metrics attract investment from venture capital.","zh-TW":"強勁的指標吸引了風險投資。"},{"en":"Attract investment by clearly articulating your value proposition.","zh-TW":"通過清晰表達價值主張來吸引投資。"}]', 'phrasal verb'),
('back-end', '後端；背後的部分', 'the behind-the-scenes systems or processes that support a product or service', '[{"en":"We improved the back-end processes to speed up delivery.","zh-TW":"我們改善了後端流程以加快交付速度。"},{"en":"Back-end improvements often have the biggest ROI.","zh-TW":"後端改進往往具有最大的投資回報率。"}]', 'business idiom'),
('balance risk and reward', '平衡風險與回報', 'to weigh potential gains against potential losses in a decision', '[{"en":"Good investors balance risk and reward carefully.","zh-TW":"優秀的投資者仔細平衡風險與回報。"},{"en":"Balance risk and reward when entering new markets.","zh-TW":"進入新市場時平衡風險與回報。"}]', 'expression'),
('be a game-changer', '是一個改變遊戲規則的事物', 'to significantly alter how something is done or perceived', '[{"en":"This new feature will be a game-changer for our users.","zh-TW":"這個新功能將是我們用戶的改變遊戲規則者。"},{"en":"Automation has been a game-changer for our logistics.","zh-TW":"自動化改變了我們物流的遊戲規則。"}]', 'expression'),
('be ahead of the pack', '領先群雄；走在前端', 'to be more advanced than competitors or peers', '[{"en":"Our early investment keeps us ahead of the pack.","zh-TW":"我們的早期投資使我們領先群雄。"},{"en":"Being ahead of the pack requires constant innovation.","zh-TW":"走在前端需要不斷的創新。"}]', 'expression'),
('be at a premium', '供不應求；有溢價', 'scarce and therefore available only at a higher price or value', '[{"en":"Office space in the city center is at a premium.","zh-TW":"市中心的辦公空間供不應求。"},{"en":"Skilled engineers are at a premium in the tech industry.","zh-TW":"在科技行業中熟練工程師供不應求。"}]', 'expression'),
('be at a standstill', '陷入停頓；僵持不前', 'completely stopped with no progress being made', '[{"en":"Negotiations are at a standstill over the pricing terms.","zh-TW":"因為定價條款談判陷入了僵持。"},{"en":"The project is at a standstill due to funding issues.","zh-TW":"由於資金問題專案陷入了停頓。"}]', 'expression'),
('be going places', '前途無量；會有大成就', 'to be on a path toward success or advancement', '[{"en":"With her skill set she''s definitely going places.","zh-TW":"憑藉她的技能她肯定前途無量。"},{"en":"High performers who are going places stay motivated.","zh-TW":"前途無量的高績效員工保持積極性。"}]', 'expression'),
('be in the black', '盈利；收支有盈餘', 'generating profit; having positive financial results', '[{"en":"After two years we''re finally in the black.","zh-TW":"兩年後我們終於開始盈利了。"},{"en":"Being in the black allows us to reinvest in growth.","zh-TW":"盈利使我們能夠再投資於增長。"}]', 'expression'),
('benchmark study', '基準研究；對標研究', 'research that compares performance metrics across similar organizations', '[{"en":"The benchmark study showed we lead on customer satisfaction.","zh-TW":"對標研究顯示我們在客戶滿意度方面領先。"},{"en":"Commission a benchmark study before setting performance targets.","zh-TW":"在設定績效目標之前委託進行對標研究。"}]', 'business idiom'),
('best-in-class', '同類最佳；業界標竿', 'the best example or standard of its kind in the market', '[{"en":"We aim to deliver best-in-class customer experience.","zh-TW":"我們致力於提供同類最佳的客戶體驗。"},{"en":"Benchmark against best-in-class performers in your sector.","zh-TW":"對比你行業中的業界標竿進行對標。"}]', 'business idiom'),
('bolt-on acquisition', '附加收購；補充性收購', 'a small acquisition that adds capability to an existing business without major integration', '[{"en":"A bolt-on acquisition added AI capability to our platform.","zh-TW":"一次附加收購為我們的平台添加了AI能力。"},{"en":"Bolt-on acquisitions are less risky than full mergers.","zh-TW":"附加收購比全面合併風險更低。"}]', 'business idiom'),
('bottom-up approach', '自下而上的方法', 'a planning process that starts with input from frontline staff or individual units', '[{"en":"A bottom-up approach to budgeting improves accuracy.","zh-TW":"自下而上的預算方法提高了準確性。"},{"en":"The bottom-up approach empowers teams and builds ownership.","zh-TW":"自下而上的方法賦能團隊並建立歸屬感。"}]', 'business idiom'),
('brand equity', '品牌資產；品牌價值', 'the commercial value derived from a brand''s name and reputation', '[{"en":"Consistent messaging builds brand equity over time.","zh-TW":"一致的信息隨著時間建立了品牌資產。"},{"en":"High brand equity allows premium pricing.","zh-TW":"高品牌資產使溢價定價成為可能。"}]', 'business idiom'),
('break the mold', '打破常規；突破固有模式', 'to do something in a completely new and different way', '[{"en":"The startup broke the mold with a subscription-free model.","zh-TW":"新創公司以無訂閱模式打破了常規。"},{"en":"Breaking the mold attracts attention but requires courage.","zh-TW":"打破固有模式吸引眼球但需要勇氣。"}]', 'expression'),
('budget envelope', '預算範圍；預算額度', 'the maximum amount of money allocated for a specific purpose', '[{"en":"We must deliver the project within the budget envelope.","zh-TW":"我們必須在預算範圍內交付這個專案。"},{"en":"Define the budget envelope before scoping the work.","zh-TW":"在規劃工作範圍之前確定預算額度。"}]', 'business idiom'),
('build a track record', '積累業績記錄；建立信譽', 'to establish a history of successful performance over time', '[{"en":"Build a track record with smaller clients before targeting enterprises.","zh-TW":"在瞄準企業客戶之前先與小型客戶積累業績記錄。"},{"en":"Building a track record takes time but is invaluable.","zh-TW":"積累業績記錄需要時間但是無價的。"}]', 'expression'),
('bundle services', '捆綁銷售服務；打包提供服務', 'to offer multiple services together as a single package', '[{"en":"We bundle services to increase average deal size.","zh-TW":"我們捆綁銷售服務以增加平均交易額。"},{"en":"Bundling services can improve customer retention.","zh-TW":"打包提供服務可以提高客戶留存率。"}]', 'phrasal verb'),
('business case', '商業案例；可行性論述', 'a justified recommendation or justification for a particular business decision', '[{"en":"Build a solid business case before requesting budget.","zh-TW":"在申請預算之前建立紮實的商業案例。"},{"en":"The business case for automation was overwhelming.","zh-TW":"自動化的商業案例十分充分。"}]', 'business idiom'),
('call out', '點名批評；提出（問題）', 'to specifically identify or criticize someone or something', '[{"en":"She called out the bottleneck in the process during the review.","zh-TW":"她在審查中點名指出了流程中的瓶頸。"},{"en":"Call out issues early rather than letting them fester.","zh-TW":"盡早提出問題而不是讓它們惡化。"}]', 'phrasal verb'),
('capacity constraint', '產能限制；資源瓶頸', 'a limitation in the ability to produce or service due to available resources', '[{"en":"We hit a capacity constraint during the peak season.","zh-TW":"旺季期間我們遭遇了產能限制。"},{"en":"Outsourcing resolved our capacity constraint overnight.","zh-TW":"外包在一夜之間解決了我們的資源瓶頸。"}]', 'business idiom'),
('capture value', '獲取價值；實現價值', 'to convert created value into revenue or profit', '[{"en":"Creating value is important but capturing value is essential.","zh-TW":"創造價值很重要但獲取價值至關重要。"},{"en":"Capture value from your intellectual property through licensing.","zh-TW":"通過許可實現知識產權的價值。"}]', 'phrasal verb'),
('cash burn rate', '現金消耗率；燒錢速度', 'the rate at which a company spends its cash reserves before generating profit', '[{"en":"Our cash burn rate gives us 18 months of runway.","zh-TW":"我們的現金消耗率給了我們18個月的資金跑道。"},{"en":"Reduce cash burn rate during slow growth periods.","zh-TW":"在增長緩慢期間降低燒錢速度。"}]', 'business idiom'),
('catch up on', '補上；補救；跟上', 'to do something that you missed or to update on something', '[{"en":"I need to catch up on the emails from last week.","zh-TW":"我需要補上上週的電子郵件。"},{"en":"Let''s catch up on the project status after the holiday.","zh-TW":"假期後讓我們跟上專案的最新狀態。"}]', 'phrasal verb'),
('center of excellence', '卓越中心；專業能力中心', 'a team or entity that provides leadership and best practices in a specific area', '[{"en":"We established a center of excellence for data analytics.","zh-TW":"我們建立了數據分析的卓越中心。"},{"en":"Centers of excellence share best practices across the organization.","zh-TW":"卓越中心在整個組織中分享最佳實踐。"}]', 'business idiom'),
('channel strategy', '渠道策略', 'the plan for how a company distributes its products or services to customers', '[{"en":"Our channel strategy combines direct sales and resellers.","zh-TW":"我們的渠道策略結合了直接銷售和分銷商。"},{"en":"Revisit your channel strategy as the market evolves.","zh-TW":"隨著市場演變重新審視你的渠道策略。"}]', 'business idiom'),
('chief concern', '主要關切；首要問題', 'the most important worry or priority at a given time', '[{"en":"Customer retention is our chief concern this quarter.","zh-TW":"客戶留存率是我們本季的首要問題。"},{"en":"What is the chief concern for investors right now?","zh-TW":"現在投資者的主要關切是什麼？"}]', 'expression'),
('choke point', '瓶頸點；阻塞點', 'a critical point where congestion or limitation severely restricts flow', '[{"en":"The inspection process is a choke point in our supply chain.","zh-TW":"檢驗流程是我們供應鏈中的瓶頸點。"},{"en":"Eliminate choke points to improve overall throughput.","zh-TW":"消除阻塞點以提高整體吞吐量。"}]', 'business idiom'),
('cold call', '冷電話；主動推銷電話', 'an unsolicited phone call or visit to a potential customer', '[{"en":"Cold calling is challenging but still effective in B2B.","zh-TW":"冷電話很有挑戰性但在B2B中仍然有效。"},{"en":"We train the team on how to make effective cold calls.","zh-TW":"我們培訓團隊如何進行有效的冷電話。"}]', 'business idiom'),
('collective responsibility', '集體責任；共同擔當', 'the shared accountability of a group for outcomes or actions', '[{"en":"Collective responsibility ensures no one blames others.","zh-TW":"集體責任確保沒有人互相推卸責任。"},{"en":"Build a culture of collective responsibility for results.","zh-TW":"建立對成果共同擔當的文化。"}]', 'expression'),
('competitive moat', '競爭護城河；持久競爭優勢', 'a durable competitive advantage that protects a company''s market position', '[{"en":"Network effects create a powerful competitive moat.","zh-TW":"網絡效應創造了強大的競爭護城河。"},{"en":"Investing in brand loyalty builds a competitive moat.","zh-TW":"投資於品牌忠誠度建立了競爭護城河。"}]', 'business idiom'),
('compound growth', '複合增長；複利式增長', 'growth that accelerates over time by building on previous gains', '[{"en":"We achieved 25% compound growth over five years.","zh-TW":"我們在五年內實現了25%的複合增長。"},{"en":"Compound growth turns small investments into significant assets.","zh-TW":"複利式增長將小投資轉變為重要資產。"}]', 'business idiom'),
('confidence interval', '信賴區間；信心範圍', 'a statistical range that indicates the reliability of an estimate', '[{"en":"The forecast has a 95% confidence interval.","zh-TW":"預測具有95%的信賴區間。"},{"en":"Understanding confidence intervals prevents overconfidence in projections.","zh-TW":"了解信賴區間防止了對預測過度自信。"}]', 'business idiom'),
('consensus-driven', '共識驅動的；基於一致意見的', 'relying on agreement from all parties before making decisions', '[{"en":"Consensus-driven decision-making is thorough but slow.","zh-TW":"基於共識的決策非常徹底但很慢。"},{"en":"A consensus-driven culture reduces conflict but requires trust.","zh-TW":"共識驅動的文化減少了衝突但需要信任。"}]', 'business idiom'),
('contextualize data', '解讀數據背景；在背景下理解數據', 'to present data in a way that considers its surrounding circumstances', '[{"en":"Contextualize the sales data within the industry downturn.","zh-TW":"在行業下滑的背景下解讀銷售數據。"},{"en":"Always contextualize data to prevent misleading conclusions.","zh-TW":"始終在背景下理解數據以防止誤導性結論。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('contingency fund', '應急基金；備用資金', 'a financial reserve set aside to cover unexpected costs or emergencies', '[{"en":"We keep a 10% contingency fund for every project.","zh-TW":"我們為每個專案保留10%的應急基金。"},{"en":"A contingency fund protects operations during cash flow gaps.","zh-TW":"應急基金在現金流缺口期間保護了業務。"}]', 'business idiom'),
('core message', '核心信息；中心訊息', 'the most important point you want your audience to take away', '[{"en":"Align all materials around the core message.","zh-TW":"讓所有材料圍繞核心信息。"},{"en":"The core message should be simple and memorable.","zh-TW":"核心信息應該簡單易記。"}]', 'expression'),
('creative tension', '創意張力；建設性衝突', 'productive conflict between differing ideas that sparks innovation', '[{"en":"Creative tension between design and engineering improves products.","zh-TW":"設計與工程之間的創意張力改善了產品。"},{"en":"Encourage creative tension as a tool for innovation.","zh-TW":"鼓勵建設性衝突作為創新工具。"}]', 'expression'),
('critical thinking', '批判性思維；批判性思考', 'the ability to analyze facts objectively to reach a reasoned conclusion', '[{"en":"Critical thinking prevents costly decision-making errors.","zh-TW":"批判性思維防止了代價高昂的決策錯誤。"},{"en":"Develop critical thinking skills through scenario training.","zh-TW":"通過情境培訓發展批判性思考技能。"}]', 'business idiom'),
('cross-border', '跨境的；跨國的', 'involving or happening across national borders', '[{"en":"Cross-border transactions require careful tax planning.","zh-TW":"跨境交易需要仔細的稅務規劃。"},{"en":"Our cross-border operations span 12 countries.","zh-TW":"我們的跨國業務跨越12個國家。"}]', 'business idiom'),
('culture fit', '文化契合度', 'the alignment between an individual''s values and behaviors and those of an organization', '[{"en":"We assess culture fit as carefully as technical skills.","zh-TW":"我們對文化契合度的評估與技術技能同樣仔細。"},{"en":"Poor culture fit is the leading cause of early employee turnover.","zh-TW":"文化契合度差是早期員工流動的主要原因。"}]', 'business idiom'),
('customer journey', '客戶旅程', 'the complete experience a customer has from first awareness to post-purchase', '[{"en":"Map the customer journey to identify friction points.","zh-TW":"繪製客戶旅程以識別摩擦點。"},{"en":"Optimize each stage of the customer journey for better retention.","zh-TW":"優化客戶旅程的每個階段以提高留存率。"}]', 'business idiom'),
('customer obsession', '以客戶為執念；極致關注客戶', 'an extreme focus on understanding and serving the customer''s needs', '[{"en":"Amazon''s customer obsession drives its competitive advantage.","zh-TW":"亞馬遜對客戶的執念推動了其競爭優勢。"},{"en":"Customer obsession means listening first and building second.","zh-TW":"以客戶為執念意味著先傾聽再建設。"}]', 'business idiom'),
('cut-throat competition', '激烈競爭；白熱化競爭', 'extremely intense and ruthless competition in a market', '[{"en":"The retail sector is known for cut-throat competition.","zh-TW":"零售行業以激烈競爭著稱。"},{"en":"In cut-throat competition differentiation is the only defense.","zh-TW":"在白熱化競爭中差異化是唯一的防禦。"}]', 'expression'),
('day-to-day basis', '日常地；以天為單位', 'happening or considered on a daily routine basis', '[{"en":"He manages the team on a day-to-day basis.","zh-TW":"他日常管理這個團隊。"},{"en":"Track KPIs on a day-to-day basis for early detection.","zh-TW":"以日常方式追蹤KPI以便早期發現問題。"}]', 'prepositional phrase'),
('deadline pressure', '截止日期壓力；時限壓力', 'the stress and urgency created by having to complete work by a set date', '[{"en":"The team performs well even under deadline pressure.","zh-TW":"團隊即使在截止日期壓力下也表現良好。"},{"en":"Deadline pressure can drive focus but also cause burnout.","zh-TW":"截止日期壓力可以驅動專注但也可能導致倦怠。"}]', 'expression'),
('deal flow', '交易流量；投資機會流入', 'the rate at which investment proposals or business deals are received', '[{"en":"Strong networking improves deal flow for the investment team.","zh-TW":"強大的人脈改善了投資團隊的交易流量。"},{"en":"High deal flow allows for selectivity in choosing partners.","zh-TW":"高交易流量使選擇合作夥伴時更具選擇性。"}]', 'business idiom'),
('decision framework', '決策框架', 'a structured approach for making consistent, objective decisions', '[{"en":"Use a decision framework to evaluate strategic options objectively.","zh-TW":"使用決策框架客觀評估策略選項。"},{"en":"A shared decision framework reduces bias.","zh-TW":"共享的決策框架減少了偏見。"}]', 'business idiom'),
('dedicated team', '專屬團隊；專職團隊', 'a group assigned exclusively to a particular client or project', '[{"en":"We assign a dedicated team to each enterprise account.","zh-TW":"我們為每個企業客戶分配一個專屬團隊。"},{"en":"A dedicated team ensures faster response and deeper expertise.","zh-TW":"專職團隊確保了更快的響應和更深的專業知識。"}]', 'expression'),
('deliberate practice', '刻意練習', 'focused, intentional practice designed to improve specific skills', '[{"en":"Deliberate practice develops negotiation skills faster.","zh-TW":"刻意練習更快地發展了談判技能。"},{"en":"Build deliberate practice into your team''s development program.","zh-TW":"將刻意練習納入團隊的發展計劃。"}]', 'expression'),
('deliver ahead of time', '提前交付；提前完成', 'to complete and hand over work before the scheduled deadline', '[{"en":"We delivered the project two weeks ahead of time.","zh-TW":"我們提前兩週交付了這個專案。"},{"en":"Delivering ahead of time builds a strong reputation.","zh-TW":"提前交付建立了良好的聲譽。"}]', 'expression'),
('demand-driven', '需求驅動的', 'responsive to customer demand rather than based on supply availability', '[{"en":"Our demand-driven production model reduces waste.","zh-TW":"我們的需求驅動生產模型減少了浪費。"},{"en":"Demand-driven strategies improve inventory efficiency.","zh-TW":"需求驅動的策略改善了庫存效率。"}]', 'business idiom'),
('democratize access', '使機會平等；普及化', 'to make something available to a wider or more diverse group of people', '[{"en":"Our platform democratizes access to financial tools.","zh-TW":"我們的平台使金融工具的機會平等。"},{"en":"Technology can democratize access to quality education.","zh-TW":"技術可以使優質教育的機會普及化。"}]', 'phrasal verb'),
('deployment roadmap', '部署路線圖', 'a plan showing the timeline and stages for rolling out a product or system', '[{"en":"Share the deployment roadmap with all stakeholders early.","zh-TW":"盡早與所有利益相關者分享部署路線圖。"},{"en":"The deployment roadmap includes three phases over six months.","zh-TW":"部署路線圖包括六個月內的三個階段。"}]', 'business idiom'),
('design for scale', '為規模化設計；可擴展設計', 'to create systems or processes with future growth in mind from the start', '[{"en":"Design for scale from day one to avoid costly rework later.","zh-TW":"從第一天就為規模化設計以避免後來代價高昂的返工。"},{"en":"Designing for scale prevents architectural bottlenecks.","zh-TW":"可擴展設計防止了架構瓶頸。"}]', 'expression'),
('differentiated value', '差異化價值；獨特的價值', 'unique benefits that distinguish a product or service from alternatives', '[{"en":"We deliver differentiated value through superior customer support.","zh-TW":"我們通過卓越的客戶支持提供差異化價值。"},{"en":"Articulate your differentiated value clearly in every pitch.","zh-TW":"在每次推介中清晰表達你的獨特價值。"}]', 'expression'),
('direct report', '直屬下屬；直接匯報的員工', 'an employee who is managed directly by a specific supervisor', '[{"en":"She manages four direct reports in the product team.","zh-TW":"她在產品團隊中管理四位直屬下屬。"},{"en":"Invest time in developing your direct reports.","zh-TW":"投入時間培養你的直屬下屬。"}]', 'business idiom'),
('distribute evenly', '均勻分配；平均分佈', 'to divide or spread something equally across all parts or people', '[{"en":"Distribute the workload evenly to prevent burnout.","zh-TW":"均勻分配工作量以防止倦怠。"},{"en":"Ensure marketing spend is distributed evenly across channels.","zh-TW":"確保行銷支出均勻分佈在各渠道。"}]', 'phrasal verb'),
('diversify revenue streams', '多元化收入來源', 'to develop multiple different sources of income to reduce dependence on any one', '[{"en":"We diversify revenue streams to reduce reliance on one client.","zh-TW":"我們多元化收入來源以減少對一個客戶的依賴。"},{"en":"Diversifying revenue streams protects against market volatility.","zh-TW":"多元化收入來源防範了市場波動。"}]', 'phrasal verb'),
('double down on strengths', '在優勢上加倍投入', 'to significantly increase focus and resources on areas where you are already strong', '[{"en":"Double down on strengths rather than trying to fix all weaknesses.","zh-TW":"在優勢上加倍投入而不是試圖修復所有弱點。"},{"en":"We doubled down on our data strengths to win enterprise clients.","zh-TW":"我們在數據優勢上加倍投入以贏得企業客戶。"}]', 'expression'),
('drive adoption', '推動採用；促進普及', 'to encourage widespread use of a product, service, or process', '[{"en":"Training and support drive adoption of new software.","zh-TW":"培訓和支持推動了新軟體的採用。"},{"en":"Incentives drive adoption in the early stages.","zh-TW":"激勵機制促進了早期階段的普及。"}]', 'phrasal verb'),
('economic headwind', '經濟逆風；不利的經濟環境', 'economic conditions that make it harder for a business to achieve its goals', '[{"en":"We maintained growth despite economic headwinds.","zh-TW":"儘管面臨經濟逆風我們仍然保持了增長。"},{"en":"Economic headwinds require conservative financial planning.","zh-TW":"不利的經濟環境需要保守的財務規劃。"}]', 'expression'),
('economic tailwind', '經濟順風；有利的經濟環境', 'economic conditions that make it easier for a business to grow', '[{"en":"We benefit from strong economic tailwinds this year.","zh-TW":"今年我們受益於強勁的經濟順風。"},{"en":"Economic tailwinds boosted our growth well above targets.","zh-TW":"有利的經濟環境推動我們的增長遠超目標。"}]', 'expression'),
('effective immediately', '即時生效；立即有效', 'taking effect right now without any delay', '[{"en":"The new policy is effective immediately.","zh-TW":"新政策即時生效。"},{"en":"The changes are effective immediately following the board vote.","zh-TW":"更改在董事會投票後立即有效。"}]', 'expression'),
('employee value proposition', '員工價值主張', 'the unique benefits offered to employees in exchange for their skills and contributions', '[{"en":"A compelling employee value proposition attracts top talent.","zh-TW":"有說服力的員工價值主張吸引了頂尖人才。"},{"en":"Review your employee value proposition annually.","zh-TW":"每年審查你的員工價值主張。"}]', 'business idiom'),
('empowerment culture', '賦權文化；授權文化', 'an organizational culture where employees are given the authority to make decisions', '[{"en":"Empowerment culture reduces bottlenecks in decision-making.","zh-TW":"賦權文化減少了決策中的瓶頸。"},{"en":"We built an empowerment culture by trusting teams with autonomy.","zh-TW":"我們通過給予團隊自主權建立了授權文化。"}]', 'business idiom'),
('end-to-end solution', '端到端解決方案；全流程解決方案', 'a product or service that covers every stage of a process from beginning to end', '[{"en":"We provide an end-to-end solution from sourcing to delivery.","zh-TW":"我們提供從採購到交付的端到端解決方案。"},{"en":"An end-to-end solution simplifies vendor management.","zh-TW":"全流程解決方案簡化了供應商管理。"}]', 'business idiom'),
('engagement rate', '參與率；互動率', 'the percentage of an audience that interacts with content or a program', '[{"en":"Our social media engagement rate doubled after the redesign.","zh-TW":"重新設計後我們的社交媒體互動率翻倍了。"},{"en":"Track engagement rate to measure content effectiveness.","zh-TW":"追蹤參與率以衡量內容有效性。"}]', 'business idiom'),
('enterprise value', '企業價值', 'the total value of a company including its debt and equity', '[{"en":"The enterprise value of the target was 500 million.","zh-TW":"目標公司的企業價值為五億。"},{"en":"Enterprise value reflects the total cost of acquisition.","zh-TW":"企業價值反映了收購的總成本。"}]', 'business idiom'),
('equity stake', '股權份額；股權比例', 'a percentage ownership in a company', '[{"en":"We offered an equity stake to key early employees.","zh-TW":"我們向關鍵早期員工提供了股權份額。"},{"en":"The investor received a 15% equity stake in exchange.","zh-TW":"投資者獲得了15%的股權份額作為交換。"}]', 'business idiom'),
('established player', '既有業者；市場老手', 'a company or organization that is already well-known and stable in a market', '[{"en":"Competing with established players requires a differentiated approach.","zh-TW":"與既有業者競爭需要差異化的方法。"},{"en":"Established players often have deep customer relationships.","zh-TW":"市場老手通常擁有深厚的客戶關係。"}]', 'business idiom'),
('event-driven', '事件驅動的', 'responding or triggered by specific events rather than time periods', '[{"en":"Event-driven marketing reaches customers at the right moment.","zh-TW":"事件驅動的行銷在正確的時機接觸客戶。"},{"en":"An event-driven architecture improves system responsiveness.","zh-TW":"事件驅動的架構提高了系統響應能力。"}]', 'business idiom'),
('execution risk', '執行風險', 'the risk that a plan will fail due to poor implementation', '[{"en":"Execution risk is often higher than strategic risk.","zh-TW":"執行風險通常高於策略風險。"},{"en":"Rigorous project management reduces execution risk.","zh-TW":"嚴格的專案管理降低了執行風險。"}]', 'business idiom'),
('expand the pie', '擴大整體利益；創造更多價值', 'to create additional value for everyone rather than fighting over a fixed amount', '[{"en":"A good negotiation expands the pie rather than just divides it.","zh-TW":"好的談判擴大整體利益而不只是分配它。"},{"en":"Think about how to expand the pie before dividing it.","zh-TW":"在分配之前思考如何擴大整體利益。"}]', 'expression'),
('expedite delivery', '加快交付；加速交貨', 'to speed up the process of delivering something', '[{"en":"We expedited delivery to meet the client''s urgent deadline.","zh-TW":"我們加快交付以滿足客戶的緊急截止日期。"},{"en":"Expedite delivery when customer satisfaction is at risk.","zh-TW":"當客戶滿意度面臨風險時加快交付。"}]', 'phrasal verb'),
('exponential growth', '指數級增長', 'growth that accelerates at an increasingly rapid rate', '[{"en":"Network effects can lead to exponential growth.","zh-TW":"網絡效應可以帶來指數級增長。"},{"en":"Few companies sustain exponential growth beyond five years.","zh-TW":"很少有公司能夠維持五年以上的指數級增長。"}]', 'business idiom'),
('fail fast', '快速失敗；早日失敗', 'to test ideas quickly so that failures can be identified and corrected early', '[{"en":"We adopt a fail fast approach to product experimentation.","zh-TW":"我們採用快速失敗的方法進行產品實驗。"},{"en":"Fail fast to avoid investing too much in the wrong direction.","zh-TW":"快速失敗以避免在錯誤方向上投入太多。"}]', 'expression'),
('feedback loop', '反饋迴路；回饋循環', 'a process where outputs are used as inputs to improve performance', '[{"en":"We built a feedback loop between sales and product development.","zh-TW":"我們在銷售和產品開發之間建立了反饋迴路。"},{"en":"Tight feedback loops accelerate product-market fit.","zh-TW":"緊密的回饋循環加速了產品市場契合度。"}]', 'business idiom'),
('financial runway', '資金跑道；可運營時間', 'the amount of time a company can operate before running out of money', '[{"en":"We have 18 months of financial runway before needing new funding.","zh-TW":"我們有18個月的資金跑道在需要新融資之前。"},{"en":"Extend your financial runway by reducing non-essential costs.","zh-TW":"通過減少非必要成本延長你的資金跑道。"}]', 'business idiom'),
('fixed cost', '固定成本', 'a cost that does not change with the level of production or sales', '[{"en":"High fixed costs create break-even pressure.","zh-TW":"高固定成本造成了收支平衡壓力。"},{"en":"Converting fixed costs to variable reduces risk.","zh-TW":"將固定成本轉為變動成本降低了風險。"}]', 'business idiom'),
('flat fee', '固定費用；統一費率', 'a single price that covers all services regardless of use or duration', '[{"en":"We charge a flat fee for the annual subscription.","zh-TW":"我們對年度訂閱收取固定費用。"},{"en":"A flat fee model gives customers predictable costs.","zh-TW":"固定費用模型讓客戶的成本可預期。"}]', 'business idiom'),
('focus on execution', '專注於執行；注重落實', 'to prioritize the actual implementation of plans over further planning', '[{"en":"It''s time to stop planning and focus on execution.","zh-TW":"是時候停止規劃而專注於執行了。"},{"en":"Focus on execution and measure outcomes weekly.","zh-TW":"專注於落實並每週衡量成果。"}]', 'expression'),
('force multiplier', '力量倍增器；放大影響的因素', 'something that greatly amplifies the effectiveness of a force or effort', '[{"en":"Good tooling acts as a force multiplier for small teams.","zh-TW":"好的工具作為小型團隊的力量倍增器。"},{"en":"A strong brand is a force multiplier in sales.","zh-TW":"強大的品牌是銷售中的力量倍增器。"}]', 'expression'),
('foreground the benefits', '突出強調好處；將好處置於前景', 'to highlight or emphasize the advantages of something prominently', '[{"en":"Foreground the benefits before mentioning the costs.","zh-TW":"在提到成本之前突出強調好處。"},{"en":"Good presentations foreground the benefits for the audience.","zh-TW":"好的演示為受眾突出強調好處。"}]', 'phrasal verb'),
('form alliances', '結盟；建立聯盟', 'to create formal agreements of cooperation between organizations', '[{"en":"We formed alliances with key distributors in new markets.","zh-TW":"我們與新市場的關鍵分銷商結盟。"},{"en":"Forming alliances can accelerate market entry.","zh-TW":"建立聯盟可以加速市場進入。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('full-stack', '全棧的；端到端的', 'covering all aspects or levels of a system or service', '[{"en":"We offer a full-stack HR solution from hire to retire.","zh-TW":"我們提供從招聘到退休的全棧人力資源解決方案。"},{"en":"Full-stack providers simplify vendor management.","zh-TW":"全棧提供商簡化了供應商管理。"}]', 'business idiom'),
('gain leverage', '獲得優勢；取得談判籌碼', 'to obtain a position of power or advantage in a situation', '[{"en":"We gain leverage by building switching costs for clients.","zh-TW":"我們通過為客戶建立轉換成本來獲得優勢。"},{"en":"Gain leverage in negotiations by understanding the other party''s needs.","zh-TW":"通過了解對方的需求在談判中取得籌碼。"}]', 'phrasal verb'),
('gap analysis', '差距分析', 'the process of comparing current performance to desired outcomes to identify gaps', '[{"en":"A gap analysis revealed weaknesses in our service delivery.","zh-TW":"差距分析揭示了我們服務交付的弱點。"},{"en":"Use gap analysis to prioritize training investments.","zh-TW":"使用差距分析來優先安排培訓投資。"}]', 'business idiom'),
('go beyond expectations', '超出預期；超越期望', 'to perform or deliver at a higher level than what was expected', '[{"en":"Our team consistently goes beyond expectations.","zh-TW":"我們的團隊始終超出預期。"},{"en":"Going beyond expectations creates loyal brand advocates.","zh-TW":"超越期望創造了忠誠的品牌擁護者。"}]', 'expression'),
('go on the record', '公開表態；留下紀錄', 'to make a statement officially or for formal documentation', '[{"en":"I want to go on the record supporting this initiative.","zh-TW":"我想公開表態支持這個計劃。"},{"en":"Going on the record shows accountability and transparency.","zh-TW":"公開表態顯示了問責制和透明度。"}]', 'expression'),
('go through channels', '通過正式渠道；按正規程序辦理', 'to follow proper official procedures rather than taking shortcuts', '[{"en":"Go through channels when requesting budget increases.","zh-TW":"申請預算增加時通過正式渠道進行。"},{"en":"She went through channels to resolve the compliance issue.","zh-TW":"她按正規程序辦理解決了合規問題。"}]', 'expression'),
('good enough', '夠用就好；足夠了', 'meeting minimum requirements without needing to be perfect', '[{"en":"In the MVP phase good enough beats perfect every time.","zh-TW":"在最小可行性產品階段夠用就好每次都優於完美。"},{"en":"Sometimes good enough allows you to move faster.","zh-TW":"有時候夠用就好讓你移動更快。"}]', 'expression'),
('granular data', '細粒度數據；精細數據', 'highly detailed data broken into small, specific categories', '[{"en":"Granular data reveals patterns invisible in aggregate views.","zh-TW":"細粒度數據揭示了彙總視圖中不可見的模式。"},{"en":"Collect granular data to improve personalization.","zh-TW":"收集精細數據以改善個性化。"}]', 'expression'),
('greenfield opportunity', '新建機會；全新未開發機會', 'an opportunity in a completely new market or situation without existing constraints', '[{"en":"The rural market is a greenfield opportunity for us.","zh-TW":"農村市場對我們來說是一個全新的未開發機會。"},{"en":"Greenfield opportunities allow you to build without legacy constraints.","zh-TW":"全新機會讓你可以不受舊有限制地建設。"}]', 'business idiom'),
('gross margin', '毛利率', 'the percentage of revenue remaining after subtracting the cost of goods sold', '[{"en":"Our gross margin improved from 35% to 42% this year.","zh-TW":"今年我們的毛利率從35%提高到了42%。"},{"en":"A higher gross margin gives more room for investment.","zh-TW":"更高的毛利率提供了更多的投資空間。"}]', 'business idiom'),
('guard against', '防範；預防', 'to take precautions to prevent something harmful from happening', '[{"en":"Guard against complacency after a successful quarter.","zh-TW":"在成功的季度後防範自滿情緒。"},{"en":"Diversify to guard against market concentration risk.","zh-TW":"通過多元化防範市場集中風險。"}]', 'phrasal verb'),
('growth hacking', '增長駭客；低成本快速增長策略', 'using creative, low-cost strategies to acquire and retain customers rapidly', '[{"en":"Our growth hacking team doubled user sign-ups in 90 days.","zh-TW":"我們的增長駭客團隊在90天內使用戶註冊翻倍了。"},{"en":"Growth hacking requires constant experimentation.","zh-TW":"增長駭客需要持續的實驗。"}]', 'business idiom'),
('growth mindset', '成長型思維', 'the belief that abilities can be developed through dedication and hard work', '[{"en":"A growth mindset turns failures into learning opportunities.","zh-TW":"成長型思維將失敗轉變為學習機會。"},{"en":"Foster a growth mindset culture to attract ambitious talent.","zh-TW":"培養成長型思維文化以吸引有抱負的人才。"}]', 'business idiom'),
('gut-check', '直覺審視；以直覺驗證', 'a check of one''s instincts or basic values before making a decision', '[{"en":"Before signing do a gut-check on whether this feels right.","zh-TW":"在簽署之前用直覺審視這是否感覺正確。"},{"en":"A gut-check is the final sanity test before committing.","zh-TW":"直覺審視是承諾之前的最後理性測試。"}]', 'expression'),
('hand off', '交接；移交', 'to pass responsibility or a task to another person', '[{"en":"She handed off the account to a new manager.","zh-TW":"她將帳戶交接給了新的經理。"},{"en":"A clean handoff prevents information loss during transitions.","zh-TW":"乾淨的交接防止了過渡期間的信息損失。"}]', 'phrasal verb'),
('hard skills', '硬技能；專業技能', 'specific, teachable technical abilities or knowledge', '[{"en":"The role requires hard skills in data analysis and coding.","zh-TW":"這個職位需要數據分析和編程方面的硬技能。"},{"en":"Pair hard skills training with soft skills development.","zh-TW":"將硬技能培訓與軟技能發展配對。"}]', 'business idiom'),
('have a say', '有發言權；有影響力', 'to have the right or opportunity to express one''s views on a matter', '[{"en":"Every team member should have a say in the planning process.","zh-TW":"每位團隊成員都應該在規劃過程中有發言權。"},{"en":"Employees want to have a say in how the company is run.","zh-TW":"員工希望對公司的運營方式有影響力。"}]', 'expression'),
('have an edge over', '在…方面具有優勢', 'to have a competitive advantage compared to someone or something', '[{"en":"We have an edge over competitors in customer support.","zh-TW":"我們在客戶支持方面比競爭對手具有優勢。"},{"en":"Proprietary technology gives us an edge over rivals.","zh-TW":"專有技術使我們在競爭對手方面具有優勢。"}]', 'expression'),
('have skin in it', '有切身利益在其中；真正有投入', 'to have a personal stake or investment in the outcome', '[{"en":"Founders who have skin in it make better long-term decisions.","zh-TW":"有切身利益的創始人做出更好的長期決策。"},{"en":"When you have skin in it you work harder for success.","zh-TW":"當你真正有投入時你更努力追求成功。"}]', 'expression'),
('high visibility project', '高曝光度專案；受矚目的專案', 'a project that is closely watched by senior leadership or the organization', '[{"en":"Leading a high visibility project accelerated her promotion.","zh-TW":"主導一個高曝光度專案加速了她的晉升。"},{"en":"High visibility projects require extra preparation and polish.","zh-TW":"受矚目的專案需要額外的準備和打磨。"}]', 'expression'),
('home run', '大成功；全壘打式的勝利', 'a major, outstanding success or achievement', '[{"en":"The product launch was a home run for the division.","zh-TW":"產品發布對這個部門來說是個大成功。"},{"en":"We hit a home run by landing the government contract.","zh-TW":"我們通過拿下政府合約取得了全壘打式的勝利。"}]', 'expression'),
('hustle culture', '拼搏文化；奮鬥文化', 'a work culture that glorifies overworking and constant productivity', '[{"en":"Hustle culture can lead to burnout if unchecked.","zh-TW":"如果不加以控制拼搏文化可能導致倦怠。"},{"en":"We prioritize results over hustle culture.","zh-TW":"我們優先考慮結果而不是奮鬥文化。"}]', 'business idiom'),
('hybrid model', '混合模式', 'combining two different approaches or structures, such as remote and in-office work', '[{"en":"We adopted a hybrid model combining in-person and online delivery.","zh-TW":"我們採用了結合線上和線下交付的混合模式。"},{"en":"A hybrid model offers flexibility for employees.","zh-TW":"混合模式為員工提供了靈活性。"}]', 'business idiom'),
('ideation process', '創意發想流程', 'the creative process of generating and developing new ideas', '[{"en":"We run a structured ideation process for product features.","zh-TW":"我們為產品功能運行結構化的創意發想流程。"},{"en":"Diverse teams produce richer ideation processes.","zh-TW":"多元化的團隊產生更豐富的創意發想流程。"}]', 'business idiom'),
('improve the bottom line', '改善盈利；提升利潤', 'to increase profit or financial performance', '[{"en":"Automation improved the bottom line by 12%.","zh-TW":"自動化將利潤改善了12%。"},{"en":"Every cost reduction initiative improves the bottom line.","zh-TW":"每項成本削減計劃都改善了盈利。"}]', 'expression'),
('in-depth analysis', '深入分析', 'a thorough and detailed examination of a topic or situation', '[{"en":"We conducted an in-depth analysis of the competitive landscape.","zh-TW":"我們對競爭格局進行了深入分析。"},{"en":"An in-depth analysis requires time but reveals critical insights.","zh-TW":"深入分析需要時間但揭示了關鍵洞察。"}]', 'expression'),
('initial public offering', '首次公開發行；上市', 'the first time a company offers shares to the public on a stock exchange', '[{"en":"The startup is preparing for an initial public offering next year.","zh-TW":"新創公司正在為明年的首次公開發行做準備。"},{"en":"An initial public offering provides capital for major expansion.","zh-TW":"首次公開發行為重大擴張提供了資金。"}]', 'business idiom'),
('insourcing', '內製；回收自製', 'bringing work that was previously outsourced back in-house', '[{"en":"We decided on insourcing IT support for better control.","zh-TW":"我們決定將IT支援內製以獲得更好的控制。"},{"en":"Insourcing critical functions reduces vendor dependency.","zh-TW":"將關鍵職能內製降低了對供應商的依賴。"}]', 'business idiom'),
('intellectual property', '知識產權；智慧財產', 'creations of the mind owned by a company, such as patents, trademarks, and copyrights', '[{"en":"Protecting intellectual property is essential for innovation.","zh-TW":"保護知識產權對創新至關重要。"},{"en":"Our intellectual property portfolio is a strategic asset.","zh-TW":"我們的知識產權組合是一個戰略資產。"}]', 'business idiom'),
('internal alignment', '內部一致；組織內部協調', 'the state in which all parts of an organization agree on and work toward common goals', '[{"en":"Internal alignment on strategy is the first step to execution.","zh-TW":"策略上的內部一致是執行的第一步。"},{"en":"Lack of internal alignment leads to conflicting initiatives.","zh-TW":"缺乏內部一致性導致計劃相互衝突。"}]', 'business idiom'),
('inventory turnover', '庫存週轉率', 'a ratio showing how many times inventory is sold and replaced in a period', '[{"en":"A higher inventory turnover improves cash flow.","zh-TW":"更高的庫存週轉率改善了現金流。"},{"en":"Track inventory turnover by product category.","zh-TW":"按產品類別追蹤庫存週轉率。"}]', 'business idiom'),
('joint venture', '合資企業；合資合作', 'a business arrangement where two companies combine resources for a project', '[{"en":"We formed a joint venture to enter the Chinese market.","zh-TW":"我們建立了合資企業以進入中國市場。"},{"en":"A joint venture shares both the risks and rewards.","zh-TW":"合資企業共享風險和回報。"}]', 'business idiom'),
('killer app', '殺手級應用；決定性功能', 'a feature or product so valuable that it justifies adopting the entire platform', '[{"en":"Our analytics dashboard is the killer app of the suite.","zh-TW":"我們的分析儀表板是這個套件的殺手級應用。"},{"en":"A killer app drives platform adoption faster than any marketing.","zh-TW":"殺手級應用比任何行銷都更快推動平台採用。"}]', 'business idiom'),
('know-how transfer', '技術轉移；知識傳遞', 'the sharing of technical skills or operational knowledge between parties', '[{"en":"The deal included a know-how transfer agreement.","zh-TW":"交易中包含了技術轉移協議。"},{"en":"Know-how transfer is essential for scaling operations.","zh-TW":"知識傳遞對於擴大業務規模至關重要。"}]', 'expression'),
('label + as', '把…標記為；將…歸類為', 'to categorize or classify something with a specific description', '[{"en":"Label the expense as marketing for easier tracking.","zh-TW":"把這筆費用標記為行銷以便更容易追蹤。"},{"en":"Avoid labeling people as low performers without sufficient data.","zh-TW":"避免在沒有足夠數據的情況下將人們歸類為低績效者。"}]', 'phrasal verb'),
('lean startup', '精益創業', 'a methodology that uses rapid prototyping and customer feedback to build businesses efficiently', '[{"en":"We follow lean startup principles to minimize waste.","zh-TW":"我們遵循精益創業原則以減少浪費。"},{"en":"Lean startup methodology accelerates learning cycles.","zh-TW":"精益創業方法加速了學習週期。"}]', 'business idiom'),
('leverage data', '善用數據；利用數據優勢', 'to use data effectively to gain insights, make decisions, or improve outcomes', '[{"en":"We leverage data to personalize the customer experience.","zh-TW":"我們善用數據個性化客戶體驗。"},{"en":"Leverage data from every touchpoint to reduce churn.","zh-TW":"利用每個接觸點的數據來降低流失率。"}]', 'phrasal verb'),
('licensing agreement', '授權協議', 'a contract granting permission to use intellectual property in exchange for compensation', '[{"en":"The licensing agreement gives us access to their patent portfolio.","zh-TW":"授權協議使我們能夠訪問他們的專利組合。"},{"en":"A licensing agreement is a low-risk market entry strategy.","zh-TW":"授權協議是低風險的市場進入策略。"}]', 'business idiom'),
('life cycle management', '生命週期管理', 'overseeing a product or asset from creation through to end of life', '[{"en":"Life cycle management prevents premature product discontinuation.","zh-TW":"生命週期管理防止了產品過早停產。"},{"en":"Track costs across the full life cycle for better decisions.","zh-TW":"追蹤整個生命週期的成本以做出更好的決策。"}]', 'business idiom'),
('limited resources', '資源有限；資源匱乏', 'having insufficient time, money, or people to accomplish all goals', '[{"en":"With limited resources we prioritized the highest-impact work.","zh-TW":"在資源有限的情況下我們優先考慮影響最大的工作。"},{"en":"Creative thinking compensates for limited resources.","zh-TW":"創意思維彌補了資源有限的不足。"}]', 'expression'),
('lock in clients', '鎖定客戶；綁定客戶', 'to secure long-term commitments from customers through contracts or switching costs', '[{"en":"Long-term contracts lock in clients and stabilize revenue.","zh-TW":"長期合約鎖定了客戶並穩定了收入。"},{"en":"We lock in clients by embedding our software into their workflow.","zh-TW":"我們通過將軟體嵌入他們的工作流程來鎖定客戶。"}]', 'phrasal verb'),
('main takeaway', '主要收穫；核心要點', 'the most important message or lesson from a presentation or discussion', '[{"en":"The main takeaway from today''s meeting is that we need more data.","zh-TW":"今天會議的主要收穫是我們需要更多數據。"},{"en":"Summarize the main takeaway at the end of every presentation.","zh-TW":"在每次演示結束時總結核心要點。"}]', 'expression'),
('market gap', '市場缺口', 'an unmet need or underserved segment in a market', '[{"en":"We identified a market gap in affordable premium fitness equipment.","zh-TW":"我們識別了實惠高端健身設備的市場缺口。"},{"en":"Addressing a market gap first can create a loyal customer base.","zh-TW":"首先填補市場缺口可以創建忠實的客戶群。"}]', 'business idiom'),
('market leader', '市場領導者；行業龍頭', 'the company with the largest market share in an industry', '[{"en":"We aim to overtake the market leader in customer service.","zh-TW":"我們的目標是在客戶服務上超越市場領導者。"},{"en":"Market leaders must innovate continuously to maintain position.","zh-TW":"市場領導者必須持續創新以保持地位。"}]', 'business idiom'),
('market research', '市場研究；市場調查', 'the systematic collection and analysis of information about a market', '[{"en":"Thorough market research shaped our product strategy.","zh-TW":"全面的市場研究塑造了我們的產品策略。"},{"en":"Market research reduces the risk of product failure.","zh-TW":"市場研究降低了產品失敗的風險。"}]', 'business idiom'),
('matrix organization', '矩陣式組織', 'a structure where employees have dual reporting relationships to both functional and project managers', '[{"en":"A matrix organization promotes collaboration across functions.","zh-TW":"矩陣式組織促進了跨職能的協作。"},{"en":"Matrix organizations can be complex to manage.","zh-TW":"矩陣式組織可能難以管理。"}]', 'business idiom'),
('merit-based', '以能力為基礎的；按功績的', 'decided or awarded based on performance and ability rather than seniority', '[{"en":"Our merit-based pay system motivates high performance.","zh-TW":"我們以能力為基礎的薪酬體系激勵了高績效。"},{"en":"Merit-based promotions reduce bias in advancement decisions.","zh-TW":"按功績晉升減少了晉升決策中的偏見。"}]', 'business idiom'),
('minimize exposure', '降低風險敞口；減少暴露', 'to reduce the degree to which one is at risk or vulnerable', '[{"en":"Hedge your positions to minimize exposure to currency risk.","zh-TW":"對冲倉位以降低匯率風險敞口。"},{"en":"Diversification minimizes exposure to any single sector.","zh-TW":"多元化減少了對任何單一行業的暴露。"}]', 'phrasal verb'),
('mission statement', '使命宣言', 'a formal declaration of an organization''s purpose and core values', '[{"en":"A clear mission statement aligns teams around a shared purpose.","zh-TW":"清晰的使命宣言使團隊圍繞共同目標保持一致。"},{"en":"Revisit your mission statement as the company evolves.","zh-TW":"隨著公司發展重新審視你的使命宣言。"}]', 'business idiom'),
('mobilize stakeholders', '動員利益相關者；召集相關方', 'to engage and activate key parties to participate in an initiative', '[{"en":"Mobilizing stakeholders early prevented resistance later.","zh-TW":"早期動員利益相關者防止了後來的阻力。"},{"en":"We mobilized stakeholders across three departments.","zh-TW":"我們動員了三個部門的利益相關者。"}]', 'phrasal verb');